class Solution:
    def maxSlidingWindow(self, nums: list[int], k: int) -> list[int]:
        q: deque[int] = deque()  # indexes; their values fall from front to back
        out: list[int] = []
        for r, x in enumerate(nums):
            while q and nums[q[-1]] <= x:
                q.pop()  # viz:pop_back
            q.append(r)  # viz:push
            l = max(0, r - k + 1)
            if q[0] < l:
                q.popleft()  # viz:expire
            if r >= k - 1:
                out.append(nums[q[0]])  # viz:record
        return out  # viz:done
